    'gf.nobody': 'Ingen annan har kort – fiska ett ur sjön!', 'gf.fishBtn': 'Fiska ett kort', 'gf.ask': 'Fråga {a}', 'gf.whom': 'Vem vill du fråga efter {r}?', 'gf.tapCard': 'Tryck på ett kort för att välja vad du vill fråga efter.',
